component = f'''import {{ useState, ReactNode }} from 'react';
interface FeatureCardProps {{ icon: ReactNode; title: string; description: string; onClick?: () => void; }}
export function FeatureCard({{icon, title, description, onClick}}: FeatureCardProps) {{
  const [isHovered, setIsHovered] = useState(false);
  const cardStyle: React.CSSProperties = {{ padding: '16px', borderRadius: '12px', boxShadow: isHovered ? '0 4px 12px rgba(0,0,0,0.08)' : '0 1px 3px rgba(0,0,0,0.04)', transition: 'box-shadow 150ms ease' }};
  return (<div style={{cardStyle}} onMouseEnter={{() => setIsHovered(true)}} onMouseLeave={{() => setIsHovered(false)}} onClick={{onClick}}><div aria-hidden='true'>{{icon}}</div><h3>{{title}}</h3><p>{{description}}</p></div>);
}}'''
with open('outputs/FeatureCard.tsx','w',encoding='utf-8') as f:
    f.write(component)
